package edu.unimagdalena.RCMU.entity;import jakarta.persistence.*;import lombok.*;@Entity@Table(name = "specialities")@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builderpublic class Speciality {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(nullable = false, unique = true)    private String name;    private String description;}